{
  "name": "Arbin电池循环测试仪",
  "name_en": "Arbin battery cycler",
  "manufacturer": "Arbin",
  "description": "用于电池与电芯充放电循环测试的多通道测试设备。它通常用于记录各通道运行状态和测量读数，支持实验室中的容量评估、循环寿命测试和电池性能表征。",
  "description_en": "A multi-channel battery test instrument used for charge-discharge cycling of batteries and cells. It is typically used to track channel status and measurement readings for laboratory capacity evaluation, cycle life testing, and battery performance characterization.",
  "tag_hints": [
    "battery cycling",
    "charge-discharge testing",
    "multi-channel cell testing",
    "battery performance characterization",
    "cycle life testing",
    "electrochemical testing"
  ],
  "actions": [
    {
      "action_name": "auto-start",
      "description": "启动电池循环测试系统运行。",
      "description_en": "Start the battery cycler operation."
    },
    {
      "action_name": "auto-update_channel_status",
      "description": "更新指定测试通道的状态和测量读数。",
      "description_en": "Update the status and measurement readings of a specified test channel."
    },
    {
      "action_name": "auto-stop",
      "description": "停止电池循环测试系统运行。",
      "description_en": "Stop the battery cycler operation."
    }
  ]
}

